namespace Bdgrz.Compliance.Features.Workforce.Models;

/// <summary>
///     A non-human identity's governed terms. <c>OwnerKind</c> is <c>person</c> or <c>team</c>
///     and <c>OwnerId</c> names exactly one accountable owner. <c>ExpiresOn</c> is an optional date
///     from which the identity must no longer be used; an active identity cannot already be expired.
/// </summary>
public sealed record ServiceIdentityTerms(string DisplayName, string IdentityKind, string Purpose,
    string? Environment, string LifecycleStatus, string OwnerKind, Uuid OwnerId, DateOnly ReviewBy,
    DateOnly? ExpiresOn = null);

namespace Bdgrz.Compliance.Features.Workforce.Events;

[Discriminator("bdgrz.workforce.service-identity.recorded", 1)]
public sealed record ServiceIdentityRecorded(Uuid TenantId, Uuid ServiceIdentityId,
    ServiceIdentityTerms Terms, ActorReference Actor, DateTimeOffset ChangedAt) : DomainEvent;

namespace Bdgrz.Compliance.Features.Workforce.Events;

[Discriminator("bdgrz.workforce.service-identity.revised", 1)]
public sealed record ServiceIdentityRevised(Uuid TenantId, Uuid ServiceIdentityId, long Revision,
    ServiceIdentityTerms Terms, ActorReference Actor, DateTimeOffset ChangedAt) : DomainEvent;
